import { jsx, jsxs } from "react/jsx-runtime";

export const Stack = ({ gap, children }) => jsx("div", { className: `stack-${gap}`, children });

export const Card = ({ title, children }) =>
  jsxs("section", { className: "card", children: [jsx("h4", { children: title }), jsx("div", { className: "card-body", children })] });
